/**
 * Genera src/generated/bundledUploadsManifest.js da uploads/ (escluso team_logos).
 * Eseguire dopo aver aggiornato i file in uploads/ prima di un build/release.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const UPLOADS_DIR = path.join(ROOT, 'uploads');
const OUT_DIR = path.join(ROOT, 'src', 'generated');
const OUT_FILE = path.join(OUT_DIR, 'bundledUploadsManifest.js');

const EXCLUDE_DIRS = new Set(['team_logos']);
const MEDIA_EXT = new Set([
  '.png', '.jpg', '.jpeg', '.gif', '.webp', '.mp4', '.webm', '.mov', '.m4v',
]);

const SLOT_FOLDERS = {
  login_logo: 'login_logo',
  login_background: 'login_background',
  app_loading: 'app_loading',
};

function walkUploads(dir, relBase = '') {
  const entries = [];
  if (!fs.existsSync(dir)) return entries;
  for (const name of fs.readdirSync(dir, { withFileTypes: true })) {
    if (name.isDirectory()) {
      if (EXCLUDE_DIRS.has(name.name)) continue;
      entries.push(...walkUploads(path.join(dir, name.name), relBase ? `${relBase}/${name.name}` : name.name));
      continue;
    }
    const ext = path.extname(name.name).toLowerCase();
    if (!MEDIA_EXT.has(ext)) continue;
    const relPath = relBase ? `${relBase}/${name.name}` : name.name;
    entries.push(`uploads/${relPath.replace(/\\/g, '/')}`);
  }
  return entries;
}

function posixRel(fromDir, toFile) {
  return path.relative(fromDir, toFile).split(path.sep).join('/');
}

function pickSlotDefaults(paths) {
  const slots = {};
  for (const [slot, folder] of Object.entries(SLOT_FOLDERS)) {
    const prefix = `uploads/${folder}/`;
    const matches = paths.filter((p) => p.startsWith(prefix)).sort();
    if (matches.length > 0) slots[slot] = matches[matches.length - 1];
  }
  return slots;
}

function main() {
  const storagePaths = walkUploads(UPLOADS_DIR).sort();
  const slotDefaults = pickSlotDefaults(storagePaths);

  const lines = storagePaths.map((storagePath) => {
    const abs = path.join(ROOT, storagePath.replace(/\//g, path.sep));
    const req = posixRel(OUT_DIR, abs);
    const key = storagePath.replace(/\\/g, '/');
    return `  '${key.replace(/'/g, "\\'")}': require('${req}'),`;
  });

  const slotLines = Object.entries(slotDefaults).map(
    ([slot, p]) => `  ${slot}: '${p.replace(/'/g, "\\'")}',`
  );

  fs.mkdirSync(OUT_DIR, { recursive: true });
  const content = `/* eslint-disable */
// AUTO-GENERATED by scripts/generateBundledUploadsManifest.js — non modificare a mano.
// Rigenerare: npm run generate:uploads-manifest

export const BUNDLED_UPLOADS = {
${lines.join('\n')}
};

/** Path Supabase predefiniti per login / loading (un file per cartella). */
export const BUNDLED_SLOT_DEFAULTS = {
${slotLines.join('\n')}
};
`;

  fs.writeFileSync(OUT_FILE, content, 'utf8');
  console.log(`Wrote ${storagePaths.length} bundled uploads → ${path.relative(ROOT, OUT_FILE)}`);
  console.log('Slot defaults:', slotDefaults);
}

main();
